const schoolTeamDefaults=[
 {name:'אבראהים גדיר',role:'מנהל בית הספר',notes:''},
 {name:'סוהיר גרוס',role:'מורה ורכזת הערכה ומדידה',notes:''},
 {name:'סאלח כעביה',role:'רכז שפה עברית',notes:''},
 {name:'מוסטפא חוג׳יראת',role:'רכז תקשוב',notes:''},
 {name:'מוחמד סאמי',role:'חבר בצוות המוביל',notes:''},
 {name:'וסים חאג',role:'חבר בצוות המוביל',notes:''}
];
function ensureSchoolTeams(){let changed=false;data.schools.forEach(school=>{const isPilotSchool=String(school.code||'').trim()==='218230';if(!Array.isArray(school.teamMembers)){school.teamMembers=isPilotSchool?schoolTeamDefaults.map(member=>({...member})):[];changed=true}if(isPilotSchool&&!school.teamNamesRevision){const corrections={'סוהיר':'סוהיר גרוס','וסים':'וסים חאג'};school.teamMembers.forEach(member=>{const corrected=corrections[String(member.name||'').trim()];if(corrected)member.name=corrected});school.teamNamesRevision=1;changed=true}});return changed}
function schoolMemberInitials(name){return String(name||'').trim().split(/\s+/).filter(Boolean).slice(0,2).map(word=>word[0]).join('')||'＋'}
function schoolTeamField(schoolIndex,memberIndex,key,label,value,type='text'){return `<label class="field">${label}${type==='textarea'?`<textarea data-team-school="${schoolIndex}" data-team-member="${memberIndex}" data-team-key="${key}" placeholder="${label}">${esc(value)}</textarea>`:`<input data-team-school="${schoolIndex}" data-team-member="${memberIndex}" data-team-key="${key}" value="${esc(value)}" placeholder="${label}">`}</label>`}
function schoolTeamMarkup(school,index){return `<div class="schoolTeamHeading"><div><p class="eyebrow">השותפים לעשייה בבית הספר</p><h3>צוות בית הספר</h3></div><span>${school.teamMembers.length} חברי צוות</span></div><div class="teamGrid schoolTeamGrid">${school.teamMembers.map((member,i)=>`<article class="person person${i%6} schoolTeamPerson"><span class="avatar" aria-hidden="true">${esc(schoolMemberInitials(member.name))}</span><small class="schoolMemberRole">${esc(member.role||'תפקיד להשלמה')}</small><h4 class="schoolMemberName">${esc(member.name||'חבר/ת צוות חדש/ה')}</h4><p class="schoolMemberNotes ${member.notes?'':'emptyNotes'}">${esc(member.notes||'אפשר להוסיף תחומי אחריות והערות.')}</p><details class="schoolMemberEdit"><summary>עריכת פרטים</summary>${schoolTeamField(index,i,'name','שם מלא',member.name)}${schoolTeamField(index,i,'role','תפקיד בבית הספר',member.role)}${schoolTeamField(index,i,'notes','תחומי אחריות והערות',member.notes,'textarea')}<button type="button" class="removeSchoolMember" data-team-remove-school="${index}" data-team-remove-member="${i}">הסרת חבר/ת צוות</button></details></article>`).join('')}</div>${school.teamMembers.length?'':'<p class="schoolTeamEmpty">טרם נוספו חברי צוות לבית הספר הזה.</p>'}<button type="button" class="add addSchoolMember" data-team-add-school="${index}">＋ הוספת חבר/ת צוות</button>${String(school.code||'').trim()==='218230'?`<p class="schoolTeamSource">מקורות לפרטי הפתיחה: <a href="https://docs.google.com/document/d/1G2sAR0-uXSPOI59SR0JbnWAh5uJYe5y22PipaGfsvpE/edit" target="_blank" rel="noopener">פרוטוקול 30/9/2026 ↗</a> ו<a href="https://docs.google.com/spreadsheets/d/1h42RvxgiaXH0DB2s82-xEzpHl-KW-UFlYseOvlv2_AI/edit" target="_blank" rel="noopener">לוח הגאנט ↗</a>. במסמכים לא צוין תפקיד ייעודי למוחמד סאמי ולחבר הצוות וסים חאג; הם מופיעים כחברי הצוות המוביל. ניתן לעדכן את הפרטים.</p>`:''}`}
const renderBeforeSchoolTeam=render;render=function(){if(ensureSchoolTeams())save();renderBeforeSchoolTeam();if(view==='schools')document.querySelectorAll('#content .school').forEach((container,index)=>{if(!data.schools[index])return;const section=document.createElement('section');section.className='schoolTeam';section.setAttribute('aria-label','צוות '+(data.schools[index].name||'בית הספר'));section.innerHTML=schoolTeamMarkup(data.schools[index],index);container.append(section)})};
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.teamKey===undefined)return;const school=data.schools[+t.dataset.teamSchool],member=school?.teamMembers?.[+t.dataset.teamMember],key=t.dataset.teamKey;if(!member||!['name','role','notes'].includes(key))return;member[key]=t.value;save();const card=t.closest('.schoolTeamPerson');if(!card)return;card.querySelector('.schoolMemberName').textContent=member.name||'חבר/ת צוות חדש/ה';card.querySelector('.schoolMemberRole').textContent=member.role||'תפקיד להשלמה';card.querySelector('.schoolMemberNotes').textContent=member.notes||'אפשר להוסיף תחומי אחריות והערות.';card.querySelector('.schoolMemberNotes').classList.toggle('emptyNotes',!member.notes);card.querySelector('.avatar').textContent=schoolMemberInitials(member.name)});
document.addEventListener('click',e=>{const add=e.target.closest('[data-team-add-school]');if(add){const index=+add.dataset.teamAddSchool,school=data.schools[index];if(!school)return;ensureSchoolTeams();school.teamMembers.push({name:'',role:'',notes:''});save();render();const section=document.querySelectorAll('#content .schoolTeam')[index];const last=section?.querySelector('.schoolTeamPerson:last-child details');if(last){last.open=true;last.querySelector('input')?.focus()}return}const remove=e.target.closest('[data-team-remove-school]');if(remove){const school=data.schools[+remove.dataset.teamRemoveSchool],index=+remove.dataset.teamRemoveMember;if(!school?.teamMembers?.[index])return;if(confirm('להסיר את '+(school.teamMembers[index].name||'חבר/ת הצוות')+' מרשימת הצוות?')){school.teamMembers.splice(index,1);save();render();toast('חבר/ת הצוות הוסר/ה מהרשימה')}}});
render();

